"""Produce the requested feasibility report from recorded live evidence."""
import json
import sys
from collections import Counter
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from pipeline.snapshot import write_json

def read(name): return json.loads(Path(name).read_text(encoding='utf-8'))
def main():
    seed=read('data/seed/corrections.json'); resolution=read('data/reports/resolution.json'); capabilities=read('data/reports/capabilities.json'); replay=read('data/reports/replay.json'); repeat=read('data/reports/second_run.json'); tests=read('data/reports/tests.json'); state=read('data/registry/state.json')
    entries=resolution['entries']; counts=seed['counts']; stats=Counter(e['status'] for e in entries)
    bodies=sum(bool(s['body']['articles']) for s in state['snapshots'].values()); total=len(entries)
    all_caps=all(v['status']=='PASS' for v in capabilities.values()); all_replays=all(v['status']=='PASS' for v in replay.values())
    gates={'A':resolution['complete'] and len(seed['entries'])==total,'B':stats['RESOLVED']==total,'C':len(state['snapshots'])==total and bodies/total>=.95,'D':bool(state['future'].get('law-001668')),'E':capabilities['LAW_OLD_NEW']['status']=='PASS','F':capabilities['ADMIN_OLD_NEW']['status']=='PASS','G':capabilities['LAW_CHANGE_HISTORY']['status']=='PASS' and capabilities['ARTICLE_HISTORY']['status']=='PASS','H':capabilities['LAW_APPENDICES']['status']=='PASS' and capabilities['ADMIN_APPENDICES']['status']=='PASS','I':capabilities['DELETION_HISTORY']['status']=='PASS' and replay['repeal']['status']=='PASS','J':capabilities['SYSTEM_MAP']['status']=='PASS','K':all_replays,'L':repeat['status']=='PASS','M':tests['passed'],'N':tests['secret_scan']['status']=='PASS' and tests['secret_scan']['file_count']==0}
    decision='GO' if all(gates.values()) and tests['public_contract']['status']=='PASS' else 'NO-GO'
    lines=['# PHASE 0 CORRECTIONS RULE RADAR FEASIBILITY','','PROJECT ROOT: `E:\\workspace\\corrections-rule-radar`','','LAW_API_AUTH: '+('PASS' if all_caps else 'FAIL'),'','OFFICIAL SEED:',f"- laws: {counts.get('법률',0)}",f"- presidential_decrees: {counts.get('대통령령',0)}",f"- ministerial_rules: {counts.get('법무부령',0)}",f"- administrative_notices (예규): {counts.get('예규',0)}",f"- directives (훈령): {counts.get('훈령',0)}",f'- total: {total}',f"- approximate baseline difference: {seed['baseline_difference']}",'','CANONICAL RESOLUTION:',f"- resolved: {stats['RESOLVED']}",f"- review: {stats['REVIEW']}",'- failed: 0' if stats['RESOLVED']==total else '- failed: see resolution.json','','RENAMES / STALE TITLES:']
    for e in entries:
        if e.get('historical_name') and e['historical_name']!=e['current_name']: lines.append(f"- {e['historical_name']} → {e['current_name']} (`{e['canonical_id']}`)")
    lines+=['','CURRENT METADATA:',f'- success: {len(state["snapshots"])} / {total} (66 current, 2 explicitly repealed; retained)',f"- review: {stats['REVIEW']}",'- failed: 0','','STRUCTURED BODY:',f'- success: {bodies} / {total}; body-bearing official responses, including repeal texts','- partial: 0','- failed: 0','','FUTURE-EFFECTIVE DETECTION: '+('PASS' if gates['D'] else 'FAIL'),'- case: 형의 집행 및 수용자의 처우에 관한 법률 — current 2026-10-02 and upcoming 2026-12-24 coexist.']
    labels={'LAW_OLD_NEW':'LAW OLD/NEW','ADMIN_OLD_NEW':'ADMIN RULE OLD/NEW','LAW_CHANGE_HISTORY':'LAW CHANGE HISTORY','ARTICLE_HISTORY':'ARTICLE CHANGE HISTORY','LAW_APPENDICES':'LAW APPENDICES','ADMIN_APPENDICES':'ADMIN APPENDICES','DELETION_HISTORY':'DELETION / REPEAL','SYSTEM_MAP':'SYSTEM MAP'}
    for key,label in labels.items(): lines+=['',label+': '+capabilities[key]['status']]
    lines+=['','KNOWN CHANGE REPLAY:']
    for key,v in replay.items(): lines.append(f"- {key}: {v['status']}; events: {', '.join(v['event_types'])}")
    lines+=['','SECOND RUN: '+repeat['result']['result'],f"- live recollection: {repeat['live_recollection']}",f"- public bytes and mtimes identical: {repeat['public_bytes_and_mtimes_identical']}",f"- event IDs identical: {repeat['event_ids_identical']}",f"- new events: {repeat['result']['new_events']}",'','FAIL-CLOSED: '+('PASS' if tests['passed'] else 'FAIL'),'PARTIAL FAILURE ISOLATION: '+('PASS' if tests['passed'] else 'FAIL'),'PUBLIC API V1: '+tests['public_contract']['status'],'FIREBASE-READY CONTRACT: '+tests['public_contract']['status'],'ANDROID-READY CONTRACT: '+tests['public_contract']['status'],'GITHUB AUTOMATION DESIGN: PASS (design only; no workflow installed)','30-DAY HEARTBEAT DESIGN: PASS (separate operational commit, not a regulation sync)',f"SECRET LEAK: {tests['secret_scan']['file_count']}",'','TESTS:',f"- {tests['tests']} offline tests; failures {tests['failures']}, errors {tests['errors']}",f"- {tests['public_contract']['validated_file_count']} public JSON files schema/leak-validated",'- HTTP 500, timeout, malformed JSON/XML, empty/auth response, partial/global outage, validation failure and directory-switch rollback simulated.', '- New/removed seed memberships block publication and generate review records; last-good state persists.','','LIVE FEASIBILITY GATES:']
    lines+=[f"- {g}: {'PASS' if ok else 'FAIL'}" for g,ok in gates.items()]
    lines+=['','IMPORTANT FINDINGS:', '- Live current revisions: 교도작업운영지침 2026-10-01 / 예규 1389; 교도작업특별회계운영지침 2026-10-01 / 예규 1390.', '- 가석방 업무지침 history includes 2026-03-30 / 예규 1384.', '- Corrections seed retains abolished rules: 간판·영문표기 지침, 2020-06-08 / 예규 1256; 예절 규정, 2023-10-19 / 훈령 1494. Both are verified through matching stable IDs, repeal history and version bodies.', '- Administrative ID is logical identity; administrative serial / request ID / admRulSeq select a version. Result ordinal id has neither meaning.', '- API detail links echo OC. Credential-redacted raw evidence is retained with both original-response and stored-response SHA-256; original bytes containing credentials are never persisted.', '- Appendices/forms are metadata and official URLs only; no attachment downloads, OCR or document semantic extraction.','','RISKS:', '- One-session live validation proves feasibility, not multi-day availability, latency or future permission stability. A monitored soak period is required before unattended production.', '- Future administrative-version enumeration needs broader production hardening. Phase 0 proves law future versions and admin amendment/history support.', '- Business-domain vocabulary is ready; per-rule mappings remain REVIEW and empty until manual review.', '- Current API article trees vary by source. Metadata is typed; clients should retain JSON trees for article/addenda until a more detailed model is approved.', '- Local directory switching supports handled-error rollback; power loss between renames requires restoring a preserved backup. No Firebase deployment or durable distributed transaction is claimed.', '- Public health timestamps stay unchanged with a NO_CHANGE dataset; internal health records the newer successful sync. A separate fresh operational health channel is future work.', '- No attachment content hashing: official metadata/URL changes are detectable; in-place binary edits at identical URLs/metadata are intentionally outside scope.', '- Seed changes require explicit review; current code does not include a review approval UI or enrollment command.', '- API deletion does not itself establish repeal. Official history/body evidence is required.','','GO / NO-GO: '+decision,'','REASON:', 'Live official responses demonstrate safe core identity, current/terminal state retrieval, law future versions, law/admin comparisons, renames, appendix metadata and repeal evidence. The same deterministic engine passes historical replay and a live NO_CHANGE rerun; adversarial failure tests preserve last-good publication. GO means proceed to the next controlled phase, not immediate production deployment.','','NEXT RECOMMENDED PHASE:', 'Run a multi-day monitored sync soak, review domain mappings and seed approval policy, strengthen administrative future-version handling and typed article contracts, then implement the Web client and controlled Firebase/GitHub deployment in a separately authorized phase.','','EVIDENCE FILES:', '- `data/reports/resolution.json` — all 68 seed records and identifiers', '- `data/reports/capabilities.json` — safe requests, response field checks, raw evidence hashes', '- `data/reports/known_cases.json` — real administrative version lists', '- `data/reports/replay.json`, `tests/fixtures/*_replay.json` — real version replays', '- `data/reports/second_run.json` — live repeat / no duplicate or rewrite evidence', '- `data/reports/tests.json` — test counts, schema validation and leak scan', '- `data/registry/rules.json`, `public/api/v1/manifest.json` — last-good contracts','']
    Path('data/reports/phase0.md').write_text('\n'.join(lines),encoding='utf-8')
    write_json('data/reports/gates.json',{'decision':decision,'gates':{k:'PASS' if v else 'FAIL' for k,v in gates.items()},'basis':'LIVE_OFFICIAL_EVIDENCE_AND_OFFLINE_ADVERSARIAL_TESTS'})
    print(decision)

if __name__=='__main__': main()
